'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'Нет данных').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const words={calm:'Спокойствие',curious:'Любопытство',anxious:'Тревога',neutral:'Нейтральное',low:'Сниженное',tender:'Нежность',frustrated:'Фрустрация',sleep:'Сон',net:'Нейросеть',heuristic:'Эвристика',rest_short:'Короткий отдых',focus_narrow:'Сузить фокус',focus_widen:'Расширить фокус',breathe_slow:'Медленное дыхание',emit_message:'Подать сигнал',explore_signal:'Исследовать',reframe_negative:'Переосмыслить',calm_baseline:'Спокойный фон',fatigue_day:'День усталости',mixed_adaptive:'Смешанный',novelty_walk:'Прогулка открытий',social_pull:'Социальный контакт',threat_pulses:'Импульсы угрозы',self_preservation:'Самосохранение',energy_conservation:'Сбережение энергии',exploration:'Исследование',attachment:'Привязанность',agency:'Самостоятельность',morning:'Утро',active:'День',evening:'Вечер',night:'Ночь'};
Object.assign(words,{focus:'Управление фокусом',restore_energy:'Восстановить энергию',body:'Тело',threat:'Угроза',novelty:'Новизна',social:'Контакт',long_term_memory:'Долговременная память',rest_recover:'Восстановление сил',regulate_breathe:'Регуляция дыхания',explore_window:'Исследование нового',break_loop:'Выход из повторений',check_social:'Проверка контакта',fatigue_high:'Высокая усталость',threat_high:'Высокая угроза',calm_novelty_window:'Новизна в спокойной обстановке',loop_warning:'Предупреждение о повторениях',evening_social_ping:'Вечерний сигнал контакта','auto.transition:drive':'Смена ведущей потребности','auto.transition:mood':'Смена настроения',manual:'По запросу',habit:'Привычка'});
const tr=v=>words[v]??v??'Нет данных', num=(v,d=0)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:d}):'—', date=v=>v?new Date(v).toLocaleString('ru-RU'):'Нет данных';
Object.assign(words,{none:'Без рекомендации',loop_break:'Прервать повтор',explore:'Исследование',connect:'Контакт',regulate:'Регуляция состояния',rest:'Восстановление сил'});
function adviceText(a){
 if(!a)return 'Связь голоса с действиями пока не передаётся хостом.';
 const labels={waiting:'Ожидаем свежую рекомендацию. Сохранённые мысли не управляют новым запуском.',disabled:'Влияние голоса на выбор отключено.',sleeping:'Сейчас действует режим сна. Голос не меняет решение о сне.',stale:'Совет устарел и больше не влияет на выбор.',context_changed:'Ситуация изменилась после наблюдения. Нужна свежая рекомендация.',none:'Голос не предложил действие.',low_confidence:'Уверенность ниже порога: совет не влияет на выбор.',urgent_recovery:'Приоритет у восстановления и безопасности. Совет не применяется.',unavailable:'Предложенное действие сейчас недоступно.',applied:'Совет учтён в оценках действий.'};
 let text=labels[a.status]||'Статус рекомендации неизвестен.';
 if(a.status==='applied')text+=a.matchesSelection?' Выбранное действие совпало с рекомендацией.':' Агент выбрал другое действие.';
 return text;
}
function renderAdvice(s){const a=s.decision?.cortexAdvice;
 $('adviceSummary').textContent=(a?.suggestedAction&&a.suggestedAction!=='none'?'Совет: '+tr(a.suggestedAction)+'. ':'')+adviceText(a);
 details('adviceDetails',[['Рекомендация',a?tr(a.suggestedAction):'Нет данных'],['Что произошло',adviceText(a)],['Выбранное действие',tr(a?.selectedAction||s.lastDecision)],['Уверенность голоса',num(a?.confidence,2)],['Наблюдение для совета',a?.frameTick!=null?'Тик '+num(a.frameTick)+' · возраст '+num(a.ageTicks)+' тиков':'Ещё нет'],['Прибавка к оценке',num(a?.scoreBias,3)],['Суточная фаза',tr(s.circadian?.phase)]]);
}
const cards=(id,rows)=>$(id).innerHTML=rows.map(([label,value])=>`<div class="card"><small>${esc(label)}</small><b>${esc(value)}</b></div>`).join('');
const details=(id,rows)=>$(id).innerHTML=rows.map(([k,v])=>`<div class="detail"><span>${esc(k)}</span>${esc(v)}</div>`).join('');
function bars(id,values,labels){$(id).innerHTML=Object.entries(labels).map(([key,label])=>`<div class="barlabel"><span>${esc(label)}</span><span>${typeof values[key]==='number'?num(values[key]*100,1)+'%':'—'}</span></div><progress max="1" value="${typeof values[key]==='number'?Math.max(0,Math.min(1,values[key])):0}" aria-label="${esc(label)}"></progress>`).join('');}
// Known status labels delimit values; spaces inside a value are preserved.
const statusKeys=['включена','включены','загружены','импорт v1.3','записей','эпизодов','опыт сценариев','индекс','кандидатов','запросов воспоминаний','последний поиск','сходство','объединено','забыто','консолидаций','последняя запись','повреждённых строк','ошибка','путь','привычек','часы привычек','несохранённых обновлений','сохранений'];
function parseStatus(raw){const out={};if(typeof raw!=='string')return out;const pattern=new RegExp('(?:^|\\s)('+statusKeys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')=','g');const matches=[...raw.matchAll(pattern)];matches.forEach((m,i)=>out[m[1]]=raw.slice(m.index+m[0].length,matches[i+1]?.index??raw.length).trim());return out;}
const field=(o,k)=>o[k]??'Нет данных';
function when(v){if(!v||!Number.isFinite(new Date(v).getTime()))return 'Нет данных';const seconds=Math.max(0,Math.floor((Date.now()-new Date(v).getTime())/1000));return (seconds<60?seconds+' с назад':seconds<3600?Math.floor(seconds/60)+' мин назад':seconds<86400?Math.floor(seconds/3600)+' ч назад':Math.floor(seconds/86400)+' д назад')+' · '+date(v);}
function reason(v){return v?String(v).split('|').map(tr).join(' · '):'Нет данных';}
function contextLabel(key){return String(key??'').split('+').map(part=>{const at=part.indexOf('=');return at<0?tr(part):({drive:'Потребность',phase:'Время',focus:'Фокус'}[part.slice(0,at)]||part.slice(0,at))+': '+tr(part.slice(at+1));}).join(' · ');}
function llmState(llm){if(llm.enabled===false)return 'Отключена';if(llm.lastError)return 'Ошибка последнего запроса';if(llm.inFlight===true)return 'Запрос выполняется';if(llm.inFlight===false)return 'Ожидает запроса';return 'Нет данных';}
function structured(x,s,status,ml,llm){
 renderForesight(s);
 const mem=parseStatus(status.memory),hab=parseStatus(status.habits),plan=s.activePlan,attention=s.attention;
 details('memory',[['Записи памяти / лимит',field(mem,'записей')],['Представлено эпизодов',field(mem,'эпизодов')],['Объединений записей',field(mem,'объединено')],['Консолидаций',field(mem,'консолидаций')],['Опыт сценариев',field(mem,'опыт сценариев')],['Последнее сохранение',when(mem['последняя запись'])],['Ошибка памяти',field(mem,'ошибка')]]);
 details('habitStatus',[['Последнее сохранение',when(hab['последняя запись'])],['Обновлений ожидает сохранения',field(hab,'несохранённых обновлений')],['Сохранений',field(hab,'сохранений')],['Импорт старого опыта',field(hab,'импорт v1.3')],['Ошибка привычек',field(hab,'ошибка')]]);
 $('habitStatus').insertAdjacentHTML('beforeend','<p class="muted">Ожидающие обновления сохраняются периодически; сам по себе этот счётчик не означает ошибку.</p>');
 $('notes').innerHTML='<p class="muted">Одна запись памяти может объединять несколько эпизодов.</p>'+(s.semanticNotesTop||[]).map(n=>`<div class="detail"><b>${esc(tr(n.bestAction))}</b><p>${esc(contextLabel(n.key))}</p><small class="muted">Наблюдений: ${esc(num(n.samples))}</small></div>`).join('');
 const habits=s.character?.habitsTop||[];
 $('habits').innerHTML=habits.map(h=>`<tr><td>${esc(tr(h.id))}<small>${esc(tr(h.cueKey))}</small></td><td>${esc(tr(h.routineAction))}</td><td>${esc(num(h.strength,3))}</td><td>${esc(num(h.routineExecutions??h.uses))}</td><td>${esc(num(h.positiveReinforcements))} / ${esc(num(h.negativeReinforcements))}</td></tr>`).join('');
 $('habitCards').innerHTML=habits.map(h=>`<div class="habitcard"><h3>${esc(tr(h.id))}</h3><p class="muted">${esc(tr(h.cueKey))}</p><div class="detail">Действие: ${esc(tr(h.routineAction))}</div><div class="habitmetrics"><div>Сила<b>${esc(num(h.strength,3))}</b></div><div>Выполнения<b>${esc(num(h.routineExecutions??h.uses))}</b></div><div>Подкрепления + / −<b>${esc(num(h.positiveReinforcements))} / ${esc(num(h.negativeReinforcements))}</b></div><div>Срабатывания стимула<b>${esc(num(h.cueExposures))}</b></div></div></div>`).join('')||'<p>Привычки пока не получены.</p>';
 details('decision',[['Действие',tr(s.decision?.actionName)],['Источник по API',tr(s.decision?.policySource)],['Причина',reason(s.decision?.reason)],['Награда',num(s.lastReward,4)],['Ведущая потребность',s.dominantDrive?tr(s.dominantDrive):'Нет данных'],['Цикл действий',s.loopInfo?.isInLoop===true?'Обнаружен':s.loopInfo?.isInLoop===false?'Не обнаружен':'Нет данных'],['Изменён ли выбор благодаря ML','API не сообщает']]);
 const goals=(s.goals||[]).map(g=>tr(typeof g==='string'?g:g.title||g.name||g.id||g.goalId)).join(', ');
 details('plan',[['Цели',goals||'Нет активных целей'],['Стратегия',plan?tr(plan.strategy):'Нет активного плана'],['Цель плана',plan?tr(plan.goalId):'—'],['Осталось тиков плана',num(plan?.remainingTicks)],['Основной фокус',tr(attention?.focus1)],['Дополнительный фокус',attention?.focus2?tr(attention.focus2):'Не указан'],['Интенсивность внимания',typeof attention?.intensity==='number'?num(attention.intensity*100,1)+'%':'—'],['Суточная фаза',tr(s.circadian?.phase)]]);
 $('decisionRaw').textContent=JSON.stringify({decision:s.decision,goals:s.goals,plan,attention,executive:s.executive},null,2);
 cards('mlCards',[['Обновления ML',num(ml.trainSteps)],['Буфер опыта / лимит',num(ml.bufferSize)+' / '+num(ml.bufferCapacity)],['Исследование ε',num(ml.epsilon,3)],['Вес сети в советнике',num(ml.netWeight,2)],['Средняя оценка Q',num(ml.avgQ,4)],['Ошибка обучения (loss)',num(ml.lastLoss,6)]]);
 cards('llmCards',[['Запрос',llmState(llm)],['Завершено',num(llm.completed)],['Последняя задержка',num(llm.lastLatencySeconds,1)+' с'],['Ошибок за запуск',num(llm.failed)]]);
 const continuity=s.continuity;
 $('continuitySummary').textContent=!continuity?.enabled?'Полное сохранение состояния ещё не включено.':continuity.restored?'Этот запуск продолжен из проверенного сохранения.':continuity.savedAt?'Полный снимок создан. Следующий запуск сможет продолжить с него.':'Первый запуск с полным сохранением. Ожидаем первый снимок.';
 details('continuityDetails',[['Последний полный снимок',when(continuity?.savedAt)],['Продолжение с шага',num(continuity?.nextTick)],['Этот запуск восстановлен с шага',num(continuity?.restoredNextTick)]]);
 cards('services',[['DeepBrain',s.tick!=null?'Тик '+num(s.tick):'Нет состояния'],['ML',ml.remoteConnected===true?'Подключён':ml.remoteConnected===false?'Нет соединения':'Нет данных'],['Ollama',llmState(llm)],['Записей в журнале',num(llm.journal?.entryCount)]]);
 details('storage',[['Последний успешный ответ LLM',when(llm.lastSuccessAt)],['Последнее сохранение памяти',when(mem['последняя запись'])],['Последнее сохранение привычек',when(hab['последняя запись'])],['Последняя запись голоса',when(llm.journal?.lastStoredAt)],['Ошибка ML',Object.hasOwn(ml,'lastRemoteError')?ml.lastRemoteError||'Нет':'Нет данных'],['Ошибка LLM',Object.hasOwn(llm,'lastError')?llm.lastError||'Нет':'Нет данных'],['Ошибка журнала',llm.journal?llm.journal.lastError||'Нет':'Нет данных']]);
 $('storage').insertAdjacentHTML('beforeend','<p class="muted">Журнал показывает сохранённые записи; число завершённых запросов считается за текущий запуск. Эти счётчики могут отличаться.</p>');
 $('storageRaw').textContent=JSON.stringify({memory:status.memory,habits:status.habits,journal:llm.journal,configVersion:s.configVersion,semanticNotes:s.semanticNotesTop,habitsDetails:habits},null,2);
}
let snapshot={},lastReceived=0;
for(const button of document.querySelectorAll('nav button'))button.onclick=()=>{for(const b of document.querySelectorAll('nav button'))b.removeAttribute('aria-current');button.setAttribute('aria-current','page');for(const s of document.querySelectorAll('.tab'))s.hidden=s.id!==button.dataset.tab;};
function render(x){snapshot=x;const s=x.state||{},status=x.status||{},ml=s.ml||{},llm=status.llm||{},thought=x.thought||{},insight=thought.insight||{},circ=s.circadian||{};
 $('epoch').textContent=x.epoch||'Ожидаем данные';
 cards('now',[['Режим',circ.isSleeping?'Спит':s.tick!=null?'Бодрствует':'—'],[s.cognition?.enabled?'Ведущая эмоция':'Настроение',tr(s.cognition?.enabled?s.cognition.dominantEmotion:s.affect?.mood)],['Действие',tr(s.lastDecision)],['Сценарий',tr(s.scenario?.name)]]);
 bars('vitals',s.homeostasis||{},{energy:'Энергия',fatigue:'Усталость',arousal:'Возбуждение',pain:'Боль',safety:'Безопасность'});
 bars('drives',s.instincts||{},{selfPreservation:'Самосохранение',energyConservation:'Сбережение энергии',exploration:'Исследование',attachment:'Привязанность',agency:'Самостоятельность'});
 $('lastThought').textContent=insight.inner_speech||'Пока нет принятых размышлений.';
 $('thoughtMeta').textContent=thought.createdAt?`${when(thought.createdAt)} · исходный тик ${num(thought.frameTick)} · принят на тике ${num(thought.acceptedAtTick)}`:'';
 $('events').innerHTML=(s.recentEvents||[]).map(e=>`<div class="event"><span class="muted">Тик ${esc(num(e.tick))}</span> · ${esc(e.payload||tr(e.type))} · интенсивность ${esc(num(e.severity,2))}</div>`).join('')||'<p class="muted">Нет событий.</p>';
 const journal=Array.isArray(x.journal)?x.journal:[];
 const journalHtml=journal.map(t=>`<article><p class="muted">${esc(date(t.createdAt))} · ${esc(reason(t.reason))} · тик ${esc(num(t.frameTick))}</p><blockquote>${esc(t.insight?.inner_speech||'Нет текста')}</blockquote><p>${esc(t.insight?.interpretation||'')}</p><p class="muted">Самооценка LLM: ${esc(num(t.insight?.confidence,2))} · принято на тике ${esc(num(t.acceptedAtTick))}</p></article>`).join('')||'<article>Журнал ещё пуст или недоступен.</article>';
 if($('journal').innerHTML!==journalHtml)$('journal').innerHTML=journalHtml;
 structured(x,s,status,ml,llm);renderAdvice(s);renderExecutive(s);renderCognition(s);renderStrategies(s);$('observe').disabled=!!llm.inFlight||!x.csrf;freshness();}
function freshness(){const now=Date.now()/1000, age=snapshot.stateAt?now-snapshot.stateAt:Infinity, frozen=snapshot.lastTickAt?now-snapshot.lastTickAt:0;const errors=Object.entries(snapshot.errors||{});const stale=Date.now()-lastReceived>15000||age>15;
 $('connection').textContent=stale?'Нет свежих данных':frozen>30?'Тик не меняется':'Данные поступают';$('freshness').textContent=Number.isFinite(age)?'Снимок получен '+Math.max(0,Math.floor(age))+' с назад':'Ожидаем первый снимок';
 $('alert').hidden=!stale&&!errors.length&&frozen<=30;$('alert').textContent=stale?'Связь потеряна или API недоступен. Показан последний полученный снимок.':frozen>30?'Тик не меняется более 30 секунд. Проверьте состояние агента.':errors.map(([k,v])=>k+': '+v).join(' · ');}
async function poll(){try{const r=await fetch('/web/snapshot');if(!r.ok)throw Error(r.status);const x=await r.json();lastReceived=Date.now();render(x);}catch{lastReceived=0;freshness();}setTimeout(poll,5000);}
let historyRows=[],historyRequest=0,selectedAt=null,chartWidth=800;
function pickPoint(index){const row=historyRows[index];if(!row){$('chartSelection').textContent='';return;}selectedAt=row.at;$('chartPoint').value=index;$('chartSelection').textContent=date(row.at*1000)+' · Энергия '+(typeof row.energy==='number'?num(row.energy*100,1)+'%':'—')+' · Безопасность '+(typeof row.safety==='number'?num(row.safety*100,1)+'%':'—');const marker=$('chartMarker');if(marker&&historyRows.length>1){const x=45+(row.at-historyRows[0].at)/(historyRows.at(-1).at-historyRows[0].at)*(chartWidth-55);marker.setAttribute('d',`M${x} 10V155`);}}
function drawHistory(rows){historyRows=rows;const svg=$('chart');chartWidth=Math.max(300,svg.clientWidth||800);svg.setAttribute('viewBox',`0 0 ${chartWidth} 180`);svg.replaceChildren();const ns='http://www.w3.org/2000/svg';function el(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;svg.append(e);return e;}
 for(const[y,label]of [[10,'100%'],[82.5,'50%'],[155,'0%']]){el('path',{d:`M45 ${y}H${chartWidth-10}`,class:'gridline'});el('text',{x:0,y:y+5,class:'axis'},label);}
 $('chartPoint').disabled=rows.length<2;$('chartPoint').max=Math.max(0,rows.length-1);
 if(rows.length<2){$('chartInfo').textContent='В этом периоде пока недостаточно истории.';$('chartSelection').textContent='';return;}
 const first=rows[0].at,last=rows.at(-1).at,gap=Math.max(120,(last-first)/rows.length*3);
 for(const[key,cls]of [['energy','series'],['safety','series safety']]){let d='',prior=null;for(const row of rows){if(typeof row[key]!=='number'){prior=null;continue;}d+=(prior===null||row.at-prior>gap?'M':'L')+(45+(row.at-first)/(last-first)*(chartWidth-55)).toFixed(1)+' '+(155-Math.max(0,Math.min(1,row[key]))*145).toFixed(1)+' ';prior=row.at;}el('path',{d,class:cls});}
 const clock=t=>new Date(t*1000).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
 for(const[x,t,anchor]of [[45,first,'start'],[(chartWidth+35)/2,(first+last)/2,'middle'],[chartWidth-10,last,'end']])el('text',{x,y:177,'text-anchor':anchor,class:'axis'},clock(t));
 el('path',{id:'chartMarker',class:'marker'});$('chartInfo').textContent=date(first*1000)+' — '+date(last*1000)+' · история с момента установки Web';
 pickPoint(selectedAt===null?rows.length-1:rows.reduce((best,row,i)=>Math.abs(row.at-selectedAt)<Math.abs(rows[best].at-selectedAt)?i:best,0));}
async function history(){const request=++historyRequest;try{const r=await fetch('/web/history?range='+$('chartRange').value);if(!r.ok)throw Error();const rows=await r.json();if(request!==historyRequest)return;drawHistory(rows);}catch{if(request===historyRequest)$('chartInfo').textContent='Не удалось обновить историю. График может быть устаревшим.';}}
$('chartRange').onchange=()=>{selectedAt=null;history();};$('chartPoint').oninput=e=>pickPoint(Number(e.target.value));
$('chart').onclick=e=>{if(historyRows.length<2)return;const box=e.currentTarget.getBoundingClientRect();const ratio=Math.max(0,Math.min(1,((e.clientX-box.left)/box.width*chartWidth-45)/(chartWidth-55)));const at=historyRows[0].at+ratio*(historyRows.at(-1).at-historyRows[0].at);pickPoint(historyRows.reduce((best,row,i)=>Math.abs(row.at-at)<Math.abs(historyRows[best].at-at)?i:best,0));};
setInterval(history,30000);
window.addEventListener('resize',()=>drawHistory(historyRows));
$('observe').onclick=async()=>{$('observe').disabled=true;try{const r=await fetch('/web/observe',{method:'POST',headers:{'X-CSRF-Token':snapshot.csrf||''}});const v=await r.json();$('observeResult').textContent=r.ok?'Запрос принят хостом. Кадр '+v.frameId+(v.auditError?' · '+v.auditError:''):v.error||'Запрос не принят';}catch{$('observeResult').textContent='Нет связи. Выполнение команды не подтверждено.';}finally{$('observe').disabled=false;}};
setInterval(freshness,1000);poll();history();

const planStages={prepare:'Подготовка',execute:'Выполнение',verify:'Проверка результата',replan:'Пересмотр способа'};
const outcomeStates={succeeded:'Достигнута',failed:'Не достигнута',interrupted:'Прервана'};
const outcomeReasons={criterion_met:'Условие подтверждено наблюдениями',no_progress:'Нет достаточного продвижения',deadline:'Истекло время выполнения',context_changed:'Изменился сценарий или эпизод',urgent_recovery:'Потребовалось восстановить безопасность',higher_priority:'Появилась более срочная цель'};
function renderExecutive(s){
 const e=s.executive,enabled=e?.enabled===true,p=e?.plan;
 $('goalOverview').hidden=!enabled;$('executivePanel').hidden=!enabled;if(!enabled)return;
 const progress=typeof p?.progress==='number'&&Number.isFinite(p.progress)?Math.max(0,Math.min(1,p.progress)):0;
 const stage=p?.status==='paused'?'Пауза на время сна':planStages[p?.stage]||'Ожидание цели';
 $('goalTitle').textContent=p?.goalTitle||'Сейчас нет незавершённой цели';
 $('goalSummary').textContent=p?stage+'. Успех: '+p.successCriterion:'Новая цель появится, когда возникнет подходящая потребность.';
 $('goalMeter').hidden=!p;$('goalMeter').value=progress;
 $('goalProgress').textContent=p?'Выполнение условия: '+num(progress*100)+'% · '+(p.evidence||'Ожидается измерение'):'Результаты предыдущих целей доступны на вкладке «Состояние».';
 details('executivePlan',p?[
  ['Цель',p.goalTitle],['Этап',stage],['Условие успеха',p.successCriterion],['Наблюдаемый результат',p.evidence],
  ['Действие в плане',tr(p.preferredAction)],['Попыток изменить способ',num(p.replans)],['Осталось шагов бодрствования',num(p.remainingTicks)]
 ]:[['Состояние','Нет незавершённого плана']]);
 $('planningStorage').textContent=e.lastError?'Не удалось сохранить план: '+e.lastError:
  (e.lastSavedAt?'План и результаты сохранены: '+date(e.lastSavedAt):'План и результаты сохраняются автоматически.')+
  (e.revalidatedAfterRestart?' После запуска результат проверяется заново.':'');
 cards('executiveStats',[['Достигнуты',num(e.succeeded)],['Не достигнуты',num(e.failed)],['Прерваны',num(e.interrupted)]]);
 $('goalOutcomes').innerHTML=(e.recentOutcomes||[]).slice(0,6).map(o=>
  '<div class="goal-outcome"><div class="titleline"><h3>'+esc(o.goalTitle)+'</h3><span class="outcome '+(['succeeded','failed','interrupted'].includes(o.status)?o.status:'')+'">'+esc(outcomeStates[o.status]||o.status)+'</span></div><p>'+esc(o.evidence)+'</p><p class="muted">'+esc(outcomeReasons[o.reason]||o.reason)+' · '+esc(date(o.at))+'</p></div>'
 ).join('')||'<p class="muted">Завершённых целей пока нет. Успех будет записан после проверки условия.</p>';
}

Object.assign(words,{curiosity:'Любопытство',joy:'Радость',fear:'Страх',sadness:'Грусть',frustration:'Фрустрация',surprise:'Удивление',relief:'Облегчение',affection:'Теплота',boredom:'Скука',succeeded:'Цель достигнута',failed:'Цель не достигнута',interrupted:'Цель прервана',novelty_opportunity:'Сигнал новизны',social_ping:'Сигнал контакта',threat_spike:'Всплеск угрозы',micro_threat:'Небольшая угроза',fatigue_wave:'Волна усталости',calm_window:'Период спокойствия'});
function cognitiveText(value){return String(value??'').replace(/\b[a-z]+(?:_[a-z]+)*\b/g,w=>words[w]??w);}
function renderCognition(s){
 const c=s.cognition,enabled=c?.enabled===true;$('cognitionContent').hidden=!enabled;
 $('cognitionAvailability').textContent=!enabled?'Расширенный когнитивный слой пока отключён или недоступен.':c.sleeping?'Сон: рабочая память и обучение ожиданиям на паузе.':'Агент оценивает ситуацию, удерживает важное и сравнивает результат с ожиданиями.';
 if(!enabled)return;
 $('dominantEmotion').textContent=tr(c.dominantEmotion);
 $('emotionGrid').innerHTML=(c.emotions||[]).map(e=>'<div class="emotion-card"><div class="barlabel"><b>'+esc(tr(e.id))+'</b><span>'+esc(num(e.intensity*100))+'%</span></div><progress max="1" value="'+Math.max(0,Math.min(1,e.intensity||0))+'" aria-label="'+esc(tr(e.id))+'"></progress><p class="muted">'+esc(e.evidence)+'</p></div>').join('');
 $('workingMemory').innerHTML=(c.workingMemory||[]).map(m=>'<div class="memory-item"><small class="muted">'+esc(({event:'Сигнал',goal:'Цель',result:'Результат',prediction:'Несовпадение ожидания',conversation:'Общение'}[m.kind]||m.kind))+' · '+esc(num(m.ageTicks))+' шагов назад</small><p>'+esc(cognitiveText(m.text))+'</p></div>').join('')||'<p class="muted">Сейчас нет удерживаемых сигналов.</p>';
 const e=c.expectation,known=e?.status==='checked';
 details('expectationDetails',[['Действие',tr(e?.action)],['Состояние',!e?'Ожидаем действие':known?'Ожидание сопоставлено с результатом':'Накапливаются первые наблюдения'],['Наблюдений до действия',num(e?.samples)],['Надёжность ожидания',known?num(e.confidence*100)+'%':'Пока недостаточно данных'],['Ожидаемый эффект',!known?'Ещё не оценивается':e.expectedUtility>0?'В сторону цели':e.expectedUtility<0?'Против направления цели':'Нейтральный'],['Ошибка ожидания',known?num(e.error*100,2)+' п.п. в среднем':'Ещё не оценивается']]);
 cards('cognitionStats',[['Наблюдений эффекта',num(c.observations)],['Изученных сочетаний «сценарий / действие»',num(c.learnedModels)],['Обработанных результатов целей',num(c.goalOutcomes)]]);
 $('cognitionStorage').textContent=c.lastError?'Не удалось сохранить: '+c.lastError:c.lastSavedAt?'Сохранено: '+date(c.lastSavedAt):'Первое сохранение ещё ожидается.';
 details('cognitionBiases',Object.entries(c.actionBiases||{}).filter(([,v])=>Math.abs(v)>.0001).map(([a,v])=>[tr(a),(v>0?'+':'')+num(v,3)]));
}

const strategyReasons={learned_results:'Выбран по результатам предыдущих попыток',learned_effects:'Учтены изученные непосредственные эффекты действий',initial_method:'Начальный способ: истории пока недостаточно',untried_alternative:'Проверяется другой способ после остановки продвижения',best_remaining_evidence:'Среди уже проверенных способов этот лучше поддержан имеющимися данными'};
const strategyContexts={steady:'Без выраженного истощения или напряжения',depleted:'Недостаток энергии или высокая усталость',strained:'Повышенное напряжение, боль или сниженная безопасность'};
const strategyDiagnoses={conditions_changed:'Изменились условия или приоритет цели',invalid_action:'Действие не прошло проверку допустимости',unavailable:'Предпочтительное действие было недоступно',not_selected:'Выбор действий не следовал этому способу',rarely_selected:'Способ выполнялся слишком редко для надёжного вывода',criterion_met:'Условие цели достигнуто; наблюдался вклад способа',criterion_met_other:'Цель достигнута без измеренного вклада способа',no_effect:'Выполнение способа не дало продвижения',insufficient_time:'Было продвижение, но истекло время',insufficient_progress:'Было продвижение, но его оказалось недостаточно'};
function strategyEffect(v){return typeof v==='number'&&Number.isFinite(v)?(v>0?'+':'')+num(v*100,2)+' п.п. за действие':'Пока недостаточно данных';}
function renderStrategies(s){
 renderIntentions(s);
 const e=s.executive,l=e?.strategyLearning,enabled=l?.enabled===true,c=l?.choice;
 $('strategyContent').hidden=!enabled;$('strategyAvailability').textContent=enabled?'Агент учитывает результаты своих попыток, доступность действий и затраты времени.':'Обучение выбору способов пока отключено или недоступно.';
 if(!enabled)return;
 $('strategyTitle').textContent=c?.title||'Ожидание новой цели';
 details('strategyChoice',c?[['Цель',e.plan?.goalTitle],['Действие сейчас',tr(e.plan?.preferredAction)],['Почему выбран',strategyReasons[c.reason]||c.reason],['Условия',strategyContexts[c.context]||c.context],['Интенсивность основного действия',c.minimumStrength>0?'Не ниже '+num(c.minimumStrength*100)+'%':'Определяется текущими потребностями'],['Предыдущих изученных попыток',num(c.samples)],['Надёжность по объёму истории',num(c.confidence*100)+'%'],['Ожидаемое продвижение',strategyEffect(c.expectedProgressPerAction)]]:[['Состояние','Сейчас нет активного способа']]);
 cards('strategyStats',[['Завершённых попыток',num(l.completedAttempts)],['Попыток с достаточными данными',num(l.learnedAttempts)],['Изученных сочетаний условий и способов',num(l.learnedContexts)]]);
 $('strategyAttempts').innerHTML=(l.recentAttempts||[]).slice(0,8).map(a=>'<div class="strategy-attempt"><div class="titleline"><h3>'+esc(a.title)+'</h3><span class="muted">'+esc(date(a.at))+'</span></div><p>'+esc(tr(a.goalId))+' · '+esc(tr(a.scenario))+'</p><div class="strategy-comparison"><div><small>Ожидал</small><strong>'+esc(strategyEffect(a.expectedProgressPerAction))+'</strong></div><div><small>Наблюдал</small><strong>'+esc(strategyEffect(a.actualProgressPerAction))+'</strong></div></div><p>'+esc(strategyDiagnoses[a.diagnosis]||a.diagnosis)+'</p><p class="muted">Выполнений: '+esc(num(a.executions))+' · шагов бодрствования: '+esc(num(a.awakeTicks))+' · недоступно: '+esc(num(a.unavailableTicks))+' · других действий: '+esc(num(a.otherActions))+' · расход энергии за попытку: '+esc(num(a.energySpent*100,1))+' п.п.</p></div>').join('')||'<p class="muted">Первая попытка ещё не завершена.</p>';
}

const intentionReasons={energy_recovery:'Нужно восстановить силы',urgent_recovery:'Нужно восстановить безопасность',higher_priority:'Появилась более срочная задача',conditions_ready:'Условия позволяют продолжить',novelty_gone:'Новизна больше не требует исследования',contact_gone:'Контакт больше не ожидает ответа',resolved_while_deferred:'Потребность удовлетворена во время другой задачи',deferred_expired:'Истёк срок ожидания возврата',capacity_limit:'Достигнут предел отложенных намерений',prerequisite_unmet:'Подцель не восстановила нужные условия',intentions_disabled:'Возврат к намерениям отключён',urgent_ancestor:'Нужен возврат к сохранённой задаче восстановления',context_changed:'Сценарий или эпизод сменился'};
Object.assign(outcomeReasons,intentionReasons);
function renderIntentions(s){
 const i=s.executive?.intentions,p=s.executive?.plan,enabled=i?.enabled===true;
 $('intentionsContent').hidden=!enabled;
 $('intentionsAvailability').textContent=enabled?'Агент удерживает главную цель, решает временные задачи и возвращается к тому, что осталось актуальным.':'Сохранение отложенных намерений пока отключено или недоступно.';
 if(!enabled)return;
 const deferred=i.deferred||[],sleeping=p?.status==='paused';
 $('intentionMain').textContent=i.mainGoalTitle||'Ожидание нового намерения';
 details('intentionCurrent',[[deferred.length?'Текущая подцель':'Текущая цель',p?.goalTitle||'Проверка условий возврата'],['Состояние',sleeping?'Пауза на время сна':p?'Выполняется':'Ожидает следующего наблюдения'],['Сохранение',s.executive.lastError?'Не удалось сохранить: '+s.executive.lastError:s.executive.lastSavedAt?'Сохранено: '+date(s.executive.lastSavedAt):'Сохраняется автоматически']]);
 $('intentionChain').innerHTML=deferred.map((d,index)=>'<div class="intention-item"><div class="titleline"><h3>'+esc((index+1)+'. '+d.goalTitle)+'</h3><span class="outcome">Отложено · '+esc(num(d.progress*100))+'%</span></div><p>'+esc(intentionReasons[d.reason]||d.reason)+'</p><p class="muted">'+esc(d.resumeCondition)+'</p><small class="muted">Сохранено шагов выполнения: '+esc(num(d.ageTicks))+' · ожидает: '+esc(num(d.deferredAwakeTicks))+' шагов бодрствования</small></div>').join('')||'<p class="muted">Отложенных намерений сейчас нет. Агент может заниматься текущей целью.</p>';
 cards('intentionStats',[['Поставлено на паузу',num(i.suspensions)],['Возвратов к намерению',num(i.resumptions)],['Отменено после проверки',num(i.cancellations)]]);
 $('intentionTransitions').innerHTML=(i.recentTransitions||[]).slice(0,6).map(t=>'<div class="intention-item"><div class="titleline"><h3>'+esc(tr(t.goalId))+'</h3><span class="outcome">'+esc(({suspended:'Отложено',resumed:'Возобновлено',cancelled:'Отменено'}[t.kind]||t.kind))+'</span></div><p>'+esc(t.evidence)+'</p><small class="muted">'+esc(intentionReasons[t.reason]||t.reason)+' · '+esc(date(t.at))+'</small></div>').join('')||'<p class="muted">Переключений с сохранением намерения ещё не было.</p>';
}

const forecastStates={learning:'Пока недостаточно опыта: выполняется обычный выбор и наблюдение за результатом.',compared:'Сравнены последствия доступных вариантов. Прогноз может дать небольшую прибавку к оценке действия.',short_horizon:'Прогноз ограничен одним шагом из-за близкой границы эпизода или сна.',urgent_recovery:'Сейчас приоритет у восстановления и безопасности. Прогноз не меняет оценки действий.',sleeping:'Агент спит. Незавершённый прогноз закрыт как частично проверенный.',episode_changed:'Начался другой эпизод. Для него будет построен новый прогноз.',checked:'Проверен',replanned:'Фактический выбор изменился',context_changed:'Изменилась ситуация или цель',prediction_mismatch:'Результат заметно разошёлся с прогнозом',invalid:'Действие не удалось проверить',checking:'Проверяется',risk:'Обнаружен риск',uncertain:'Недостаточная уверенность',evaluated:'Оценён',unknown:'Ещё нет модели'};
const forecastProgress=v=>typeof v==='number'?(v>0?'+':'')+num(v*100,2)+' п.':'—';
function renderForesight(s){
 const f=s.foresight;
 $('forecastReason').textContent=!f?.enabled?'Прогнозирование ещё не включено.':forecastStates[f.status]||'Ожидаем оценку.';
 details('forecastChoice',[['Текущая цель',s.executive?.plan?.goalTitle||'Поддержание состояния'],['Рекомендация прогноза',f?.recommendedAction?tr(f.recommendedAction):'Пока нет'],['Фактически выбрано',f?.selectedAction?tr(f.selectedAction):'Ещё не выбрано'],['Влияние на выбор',f?.appliedBias>0?'Учтено вместе с другими оценками':'Оценки действий не менялись']]);
 $('forecastOptions').innerHTML=(f?.options||[]).map(o=>{
  const last=o.steps?.at(-1)?.expected,path=(o.steps||[]).map(st=>tr(st.action)).join(' → ');
  return `<article class="forecast-option"><h3>${esc(tr(o.firstAction))}${o.firstAction===f.selectedAction?' · выбран':''}</h3><p>${esc(path||'Для прогноза нужны наблюдения')}</p><p class="muted">${esc(forecastStates[o.status]||o.status)} · уверенность ${esc(num(o.confidence*100))}%</p>${last?`<div class="detail"><span>Энергия в конце пути</span>${esc(num(last.body.energy*100,1))}%</div><div class="detail"><span>Усталость</span>${esc(num(last.body.fatigue*100,1))}%</div><div class="detail"><span>Безопасность</span>${esc(num(last.body.safety*100,1))}%</div><div class="detail"><span>Эмоциональное возбуждение</span>${esc(num(last.arousal*100,1))}%</div><div class="detail"><span>Эмоциональный тон (−1…+1)</span>${esc(num(last.valence,2))}</div><div class="detail"><span>Продвижение по критерию</span>${esc(forecastProgress(o.expectedProgress))}</div>`:''}</article>`;
 }).join('')||'<p class="muted">Варианты появятся при следующем выборе действия.</p>';
 const a=f?.activeForecast;
 details('forecastActive',a?[['Текущая проверка',tr(a.firstAction)+' · '+num(a.checkedSteps)+' из '+num(a.plannedSteps)+' шагов'],['Прогноз на весь путь / наблюдается',forecastProgress(a.expectedProgress)+' / '+forecastProgress(a.actualProgress)]]:[['Текущая проверка','Сейчас нет незавершённого прогноза']]);
 $('forecastHistory').innerHTML=(f?.recentChecks||[]).slice(0,12).map(h=>`<tr><td>${esc(tr(h.firstAction))}</td><td>${esc(num(h.checkedSteps))} / ${esc(num(h.plannedSteps))}</td><td>${esc(forecastProgress(h.expectedProgress))} / ${esc(forecastProgress(h.actualProgress))}</td><td>${h.meanError==null?'—':esc(num(h.meanError*100,2))+' п.п.'}</td><td>${esc(forecastStates[h.status]||h.status)}</td></tr>`).join('')||'<tr><td colspan="5">Проверенные результаты ещё не накоплены.</td></tr>';
 cards('forecastStats',[['Оценок выбора',num(f?.predictions)],['Проверено шагов',num(f?.checkedSteps)],['Полностью проверено цепочек',num(f?.completedPlans)],['Изученных моделей действия',num(f?.learnedModels)]]);
}

let dialogueView=null,dialogueSending=false,dialogueAttempt=null;
function dialogueButtons(){const pending=dialogueView?.history?.some(r=>r.status==='pending');$('dialogueSend').disabled=dialogueSending||pending||!dialogueView?.ready||!snapshot.csrf;$('dialogueNew').disabled=dialogueSending||pending;}
function renderDialogue(v){
 dialogueView=v;
 const local=v.provider==='ollama',automatic=local&&v.fallbackEnabled,server=v.activeBackend==='server';
 $('dialogueModel').textContent=v.model||'Нет доступной модели';
 $('dialogueConnection').textContent=v.configurationError?'Нужна проверка настроек':!v.enabled?'Диалог выключен':local?(v.connection==='online'?(server?'Qwen 4B · резерв на сервере':'Qwen 9B · компьютер подключён'):automatic?'Обе модели Qwen недоступны':v.connection==='model_missing'?'Qwen ещё не загружен':'Компьютер с Qwen недоступен'):!v.keyConfigured?'Ожидаем API-ключ':'Готов к запросам OpenAI';
 $('dialoguePrivacy').textContent=local?'Ответы готовит Qwen. Лада получает недавнюю переписку, найденные детали прошлых разговоров и текущее состояние DeepBrain. Вся переписка хранится на сервере DeepBrain; облачные API не используются.':'Ответы через OpenAI. При отправке передаются сообщение, недавняя переписка и краткий снимок состояния агента. Переписка сохраняется на сервере и становится частью опыта общения DeepBrain.';
 $('dialogueUsage').textContent=`Запросов сегодня: ${num(v.requestsToday)} из ${num(v.dailyRequests)} · день по UTC. История сохраняется при перезапуске.`;
 $('dialogueSetup').textContent=v.configurationError||(automatic?'Показана модель для следующего сообщения. Когда компьютер недоступен, отвечает серверный 4B; после восстановления связи возвращается 9B. У обеих моделей общая переписка. Резерв отвечает медленнее, короче и учитывает меньше недавнего контекста.':local?'Для общения компьютер должен быть включён, а локальное подключение — запущено. Вход в Windows запускает его автоматически.':!v.keyConfigured?'Ключ вводится в терминале сервера скрытым вводом. Не вставляй его в переписку.':'Точное списание и остаток средств доступны в кабинете OpenAI.');
 $('dialogueCost').textContent=(local?'Локальная обработка без оплаты API. ':'Отправка расходует квоту OpenAI. ')+'Твои сообщения влияют на эмоции Лады и сохраняются в опыте общения.';
 $('dialogueHistory').innerHTML=(v.history||[]).map(r=>`<div class="dialogue-entry user"><span class="muted">Ты · ${esc(new Date(r.at*1000).toLocaleString('ru-RU'))}</span><p>${esc(r.message)}</p></div><div class="dialogue-entry assistant"><span class="muted">${esc(r.model)}${r.backend==='server'?' · резерв на сервере':r.backend==='desktop'?' · компьютер':''}</span><p>${esc(r.status==='completed'?r.answer:r.status==='pending'?'Готовлю ответ…':r.error||'Ответ не получен')}</p>${r.finishReason==='length'?'<p class="muted">Достигнут лимит короткого ответа. Можно попросить продолжить.</p>':''}${r.usage?.total_tokens!=null?`<span class="muted">Токенов: ${num(r.usage.total_tokens)}</span>`:''}</div>`).join('')||'<article><p class="muted">Здесь появится ваша переписка.</p></article>';
 dialogueButtons();
}
async function loadDialogue(){try{const r=await fetch('/web/dialogue');const v=await r.json();if(!r.ok)throw Error(v.error);renderDialogue(v);}catch(e){$('dialogueConnection').textContent=e.message||'Нет связи с сервером';dialogueView=null;dialogueButtons();}}
$('dialogueForm').onsubmit=async e=>{
 e.preventDefault();const message=$('dialogueMessage').value.trim();if(!message||!dialogueView?.ready||dialogueSending)return;
 if(!dialogueAttempt||dialogueAttempt.message!==message||dialogueAttempt.conversationId!==dialogueView.conversationId){const bytes=crypto.getRandomValues(new Uint8Array(16));dialogueAttempt={requestId:Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join(''),conversationId:dialogueView.conversationId,message};}
 dialogueSending=true;dialogueButtons();$('dialogueResult').textContent='Запрос отправляется. Ожидаем ответ…';
 try{const r=await fetch('/web/dialogue/message',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':snapshot.csrf||''},body:JSON.stringify(dialogueAttempt)});const v=await r.json();$('dialogueResult').textContent=r.ok?'Ответ получен.':v.error||'Ответ не получен.';if(v.requestId){dialogueAttempt=null;$('dialogueMessage').value='';}else if(v.errorCode!=='busy'){dialogueAttempt=null;}}
 catch{$('dialogueResult').textContent='Связь прервалась. Проверь историю перед повтором; повторная отправка этого же запроса не запускает обработку повторно.';}
 finally{dialogueSending=false;await loadDialogue();dialogueButtons();}
};
$('dialogueNew').onclick=async()=>{if(dialogueSending)return;try{const r=await fetch('/web/dialogue/new',{method:'POST',headers:{'X-CSRF-Token':snapshot.csrf||''}});const v=await r.json();if(!r.ok)throw Error(v.error);dialogueAttempt=null;renderDialogue(v);$('dialogueResult').textContent='Начат новый диалог. Предыдущая переписка сохранена.';}catch(e){$('dialogueResult').textContent=e.message||'Не удалось начать диалог.';}};
async function loadAlice(){try{const r=await fetch('/web/alice');if(!r.ok)throw Error();const v=await r.json();$('aliceStatus').textContent=v.paired?'Аккаунт Яндекса подключён. '+(v.pending?'Готовится голосовой ответ.':'Скажи: «Алиса, запусти навык Моя Лада».'):v.configured?'Навык настроен. Получи код и произнеси его в навыке по цифрам.':'Голосовой обработчик установлен. Для подключения нужны адрес HTTPS и приватный навык в Яндекс Диалогах.';$('alicePair').hidden=!v.configured||v.paired;$('aliceAuthorize').hidden=!v.paired||v.stationAuthorized;$('aliceAuthorize').disabled=['starting','waiting'].includes(v.authorizationState);$('aliceDevicePanel').hidden=true;if(v.authorizationState==='waiting'&&v.authorizationMethod==='device'&&v.authorizationVerificationUrl){const u=new URL(v.authorizationVerificationUrl);if(u.protocol==='https:'&&['ya.ru','oauth.yandex.ru','oauth.yandex.com'].includes(u.hostname)&&u.pathname==='/device'){$('aliceDeviceCode').textContent=v.authorizationUserCode||'';$('aliceDeviceLink').href=u.href;$('aliceDevicePanel').hidden=false;$('aliceDeviceTime').textContent='Код действует ещё около '+Math.max(0,v.authorizationSecondsRemaining||0)+' с.';}}else{$('aliceDeviceCode').textContent='';$('aliceDeviceLink').removeAttribute('href');}$('aliceAutomatic').hidden=!v.stationAuthorized;$('aliceAutomatic').dataset.enabled=String(!!v.automaticReplyEnabled);$('aliceAutomatic').textContent=v.automaticReplyEnabled?'Выключить автоозвучивание':'Включить автоозвучивание';$('aliceDelivery').textContent=v.automaticReplyEnabled?(v.automaticReplyState==='uncertain'?'Доставка последнего ответа не подтверждена. Ответ сохранён в переписке; его можно запросить голосом.':v.stationReachable?'Готовые ответы озвучиваются на Станции Макс автоматически.':'Проверяю связь с Макс. Если автоозвучивание недоступно, ответ можно запросить голосом.'):'Автоозвучивание выключено.';if(['starting','waiting','expired','failed'].includes(v.authorizationState)||(v.authorizationState==='connected'&&!v.automaticReplyEnabled)){$('aliceDelivery').textContent=({starting:'Получаю код входа…',waiting:'Открой страницу Яндекса и подтверди вход кодом выше. DeepBrain проверит результат автоматически.',expired:'Время входа истекло. Нажми «Подключить автоозвучивание», чтобы получить новый код.',failed:'Вход не завершён. Можно повторить подключение.',connected:'Вход выполнен. Можно проверить и включить автоозвучивание.'})[v.authorizationState];}}catch{$('aliceStatus').textContent='Не удалось проверить подключение Станции.';}}
$('alicePair').onclick=async()=>{try{const r=await fetch('/web/alice/pair',{method:'POST',headers:{'X-CSRF-Token':snapshot.csrf||''}});const v=await r.json();if(!r.ok)throw Error(v.error);$('aliceCode').textContent=`Код: ${v.code.split('').join(' ')}. Действует 10 минут. Произнеси его только своему навыку.`;}catch(e){$('aliceCode').textContent=e.message||'Не удалось получить код.';}};
document.querySelector('button[data-tab="dialogue"]').addEventListener('click',()=>{loadDialogue();loadAlice();});
setInterval(()=>{if(!$('dialogue').hidden){loadDialogue();loadAlice();}},5000);
loadDialogue();

$('aliceAutomatic').onclick=async()=>{const b=$('aliceAutomatic');b.disabled=true;try{const r=await fetch('/web/alice/automatic',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':snapshot.csrf||''},body:JSON.stringify({enabled:b.dataset.enabled!=='true'})});const v=await r.json();if(!r.ok)throw Error(v.error);await loadAlice();}catch(e){$('aliceDelivery').textContent=e.message||'Не удалось изменить настройку.';}finally{b.disabled=false;}};

$('aliceAuthorize').onclick=async()=>{const b=$('aliceAuthorize');b.disabled=true;try{const r=await fetch('/web/alice/authorize',{method:'POST',headers:{'X-CSRF-Token':snapshot.csrf||''}});const v=await r.json();if(!r.ok)throw Error(v.error);await loadAlice();}catch(e){$('aliceDelivery').textContent=e.message||'Не удалось начать вход.';b.disabled=false;}};

$('aliceDeviceRefresh').onclick=async()=>{const b=$('aliceDeviceRefresh');b.disabled=true;try{const r=await fetch('/web/alice/authorize/refresh',{method:'POST',headers:{'X-CSRF-Token':snapshot.csrf||''}});const v=await r.json();if(!r.ok)throw Error(v.error);await loadAlice();}catch(e){$('aliceDelivery').textContent=e.message||'Не удалось получить новый код.';}finally{b.disabled=false;}};

async function loadLada(){try{const r=await fetch('/web/lada');if(!r.ok)return;const v=await r.json(),f=v.face||{};$('ladaMood').textContent=(f.emoji||'—')+' '+(f.label||'');$('ladaDisplay').textContent=f.enabled?(f.status==='displayed'?'Настроение передано на экран Макс.':f.status==='stale'?'Ожидаем свежий снимок DeepBrain.':'Экран обновляется, когда Станция свободна от разговора и музыки.'):'Отображение на Станции выключено.';renderConversationExperience(v.experience);$('ladaMemoryInfo').textContent='Для поиска доступны '+num(v.memory.indexedMessages)+' сообщений. Закреплённые сведения:';$('ladaFacts').innerHTML=(v.memory.facts||[]).map(x=>'<p>'+esc(x.text)+' <small class="muted">'+esc(new Date(x.at*1000).toLocaleDateString('ru-RU'))+'</small></p>').join('')||'<p class="muted">Пока нет отдельных фактов; прошлые разговоры уже доступны для поиска.</p>';}catch{}}
let ladaArchiveBefore=0,ladaArchiveLoaded=false,ladaArchiveBusy=false;
async function loadLadaArchive(){if(ladaArchiveBusy||ladaArchiveBefore===null)return;ladaArchiveBusy=true;try{const r=await fetch('/web/dialogue/archive?before='+ladaArchiveBefore);if(!r.ok)throw Error();const v=await r.json();$('ladaArchive').insertAdjacentHTML('afterbegin',v.history.map(x=>'<div class="dialogue-entry"><small class="muted">'+esc(new Date(x.at*1000).toLocaleString('ru-RU'))+'</small><p><b>Ты:</b> '+esc(x.message)+'</p><p><b>Лада:</b> '+esc(x.answer||x.error||'Нет ответа')+'</p></div>').join(''));ladaArchiveBefore=v.before;ladaArchiveLoaded=true;$('ladaArchiveMore').hidden=v.before===null;}finally{ladaArchiveBusy=false;}}
$('ladaArchivePanel').ontoggle=()=>{if($('ladaArchivePanel').open&&!ladaArchiveLoaded)loadLadaArchive().catch(()=>{$('ladaArchive').textContent='Не удалось открыть архив. Повтори загрузку.';});};
$('ladaArchiveMore').onclick=()=>loadLadaArchive().catch(()=>{});
setInterval(()=>{if(!$('dialogue').hidden)loadLada();},5000);loadLada();

function renderConversationExperience(bridge){
 const e=snapshot?.state?.conversation,el=$('ladaExperience');
 if(!e?.enabled){el.textContent='Связь разговоров с эмоциями: ожидаем состояние DeepBrain.';return;}
 const mood=Object.entries(e.emotionInfluence||{}).filter(([,v])=>v>.01).sort((a,b)=>b[1]-a[1]);
 const pending=bridge?.analyzing?'Qwen оценивает смысл последнего сообщения…':bridge?.error?'Связь с ядром временно недоступна. Сообщения сохранены и будут учтены после восстановления.':bridge?.pending?'Передаём новые сообщения в опыт…':'Новые сообщения учитываются автоматически.';
 el.innerHTML='<h3>Опыт общения</h3><p>Сообщений в опыте: '+esc(num(e.experiences))+' · учтено в эмоциональном состоянии: '+esc(num(e.emotionalExchanges))+'.</p><p class="muted">'+esc(pending)+'</p>'+
 (bridge?.lastAssessment?'<p><b>Оценка смысла</b><br>'+esc(bridge.lastAssessment.reason)+'<br><small class="muted">'+esc(bridge.lastAssessment.semantic.source==='qwen'?'Qwen · '+({none:'без признаков иронии',possible:'возможна ирония',likely:'вероятна ирония'}[bridge.lastAssessment.semantic.irony]||'')+(bridge.lastAssessment.semantic.ambiguous||bridge.lastAssessment.semantic.confidence<.6?' · смысл неоднозначен':''):'Оценка недоступна')+'</small></p>':'')+
 (e.lastEmotional?'<p><b>' +esc(e.lastEmotional.label)+'</b><br><small class="muted">'+esc(date(e.lastEmotional.at))+'</small></p>':'<p class="muted">Старая переписка сохранена как опыт. Ждём нового разговора.</p>')+
 '<p>'+esc(mood.length?'Сейчас общение усиливает: '+mood.slice(0,3).map(([k])=>tr(k).toLowerCase()).join(', '):'Эмоциональное влияние прошлой беседы уже ослабло; опыт сохранился.')+'</p><p class="muted">Qwen оценивает смысл с учётом предыдущих реплик, в том числе возможную иронию. Неуверенная оценка не меняет эмоции. Влияние плавно ослабевает. Во сне опыт сохраняется, эмоции обновляются после пробуждения.</p>';
}
